{ config, lib, pkgs, ... }:
let
  # Every file under files/prometheus is installed at /etc/prometheus/<same relative path>.
  promRoot = toString ./files/prometheus;
  promEtc = builtins.listToAttrs (map
    (p: lib.nameValuePair
      "prometheus/${lib.removePrefix (promRoot + "/") (toString p)}"
      { source = p; })
    (lib.filesystem.listFilesRecursive ./files/prometheus));

  alertSink = pkgs.writeScript "alert-sink"
    ("#!${pkgs.python3}/bin/python3\n" + builtins.readFile ./files/bin/alert-sink.py);

  inventory = pkgs.writeScript "node31-inventory"
    ("#!${pkgs.runtimeShell}\n"
      + "export PATH=${lib.makeBinPath [ pkgs.gawk pkgs.coreutils ]}\n"
      + builtins.readFile ./files/bin/node31-inventory.sh);
in
{
  networking.hostName = "node31";
  networking.hosts."127.0.0.1" = [ "node31" "node31.n31.test" ];
  networking.firewall.enable = false;

  time.timeZone = "Etc/UTC";
  i18n.defaultLocale = "C.UTF-8";

  # ---- accounts -------------------------------------------------------------
  users.groups = {
    reed.gid = 1401;
    sage.gid = 1402;
    prometheus.gid = 120;
    www-data.gid = 33;
    sudo.gid = 27;
    admin.gid = 117;
  };

  users.users = {
    reed = {
      isNormalUser = true;
      uid = 1401;
      group = "reed";
      home = "/home/reed";
      homeMode = "750";
      shell = pkgs.bashInteractive;
      hashedPassword = "!";
    };
    sage = {
      isNormalUser = true;
      uid = 1402;
      group = "sage";
      home = "/home/sage";
      homeMode = "750";
      shell = pkgs.bashInteractive;
      hashedPassword = "!";
    };
    prometheus = {
      isSystemUser = true;
      uid = 112;
      group = "prometheus";
      description = "Prometheus daemon";
      home = "/var/lib/prometheus";
      createHome = false;
      shell = "/run/current-system/sw/bin/nologin";
    };
    www-data = {
      isSystemUser = true;
      uid = 33;
      group = "www-data";
      description = "www-data";
      home = "/var/www";
      createHome = false;
      shell = "/run/current-system/sw/bin/nologin";
    };
  };

  security.sudo.extraRules = [
    {
      groups = [ "sudo" "admin" ];
      runAs = "ALL:ALL";
      commands = [ { command = "ALL"; options = [ ]; } ];
    }
  ];

  # ---- ssh ------------------------------------------------------------------
  # PermitRootLogin = prohibit-password and root's authorized key come from the harness.
  services.openssh = {
    enable = true;
    settings = {
      PasswordAuthentication = false;
      KbdInteractiveAuthentication = false;
      X11Forwarding = true;
      PrintMotd = false;
      AcceptEnv = [ "LANG" "LC_*" ];
    };
    hostKeys = [
      { path = "/etc/ssh/ssh_host_rsa_key"; type = "rsa"; bits = 4096; }
      { path = "/etc/ssh/ssh_host_ecdsa_key"; type = "ecdsa"; }
      { path = "/etc/ssh/ssh_host_ed25519_key"; type = "ed25519"; }
    ];
  };

  # ---- nginx: http->https redirect, TLS front end, basic auth, reverse proxies --
  services.nginx = {
    enable = true;
    user = "www-data";
    group = "www-data";
    config = ''
      user www-data;
      worker_processes auto;
      pid /run/nginx.pid;

      events {
        worker_connections 768;
      }

      http {
        sendfile on;
        tcp_nopush on;
        types_hash_max_size 2048;

        include ${pkgs.nginx}/conf/mime.types;
        default_type application/octet-stream;

        ssl_protocols TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;
        ssl_prefer_server_ciphers on;

        access_log /var/log/nginx/access.log;
        error_log /var/log/nginx/error.log;

        gzip on;

        include /etc/nginx/conf.d/*.conf;
      }
    '';
  };

  # ---- monitoring stack -----------------------------------------------------
  systemd.services = {
    prometheus = {
      description = "Monitoring system and time series database";
      documentation = [ "https://prometheus.io/docs/introduction/overview/" ];
      after = [ "network.target" ];
      wantedBy = [ "multi-user.target" ];
      serviceConfig = {
        Restart = "on-failure";
        User = "prometheus";
        Group = "prometheus";
        EnvironmentFile = "/etc/default/prometheus";
        ExecStart = "${pkgs.prometheus}/bin/prometheus $ARGS";
        ExecReload = "${pkgs.util-linux}/bin/kill -HUP $MAINPID";
        TimeoutStopSec = "20s";
        SendSIGKILL = false;
        NoNewPrivileges = true;
        PrivateTmp = true;
        ProtectHome = true;
        ProtectSystem = "full";
      };
    };

    prometheus-alertmanager = {
      description = "Alertmanager for prometheus";
      documentation = [ "https://prometheus.io/docs/alerting/alertmanager/" ];
      after = [ "network.target" ];
      wantedBy = [ "multi-user.target" ];
      serviceConfig = {
        Restart = "on-failure";
        User = "prometheus";
        Group = "prometheus";
        EnvironmentFile = "/etc/default/prometheus-alertmanager";
        ExecStart = "${pkgs.prometheus-alertmanager}/bin/alertmanager $ARGS";
        ExecReload = "${pkgs.util-linux}/bin/kill -HUP $MAINPID";
        TimeoutStopSec = "20s";
        SendSIGKILL = false;
        NoNewPrivileges = true;
        PrivateTmp = true;
        ProtectHome = true;
        ProtectSystem = "full";
      };
    };

    prometheus-blackbox-exporter = {
      description = "Blackbox exporter for Prometheus";
      documentation = [ "https://prometheus.io/docs/introduction/overview/" ];
      after = [ "network.target" ];
      wantedBy = [ "multi-user.target" ];
      serviceConfig = {
        Restart = "on-failure";
