  users.groups = {
    reed.gid = 1401;
    sage.gid = 1402;
    prometheus.gid = 120;
    www-data.gid = 33;
    sudo.gid = 27;
    admin.gid = 117;
  };

  users.users = {
    reed = {
      isNormalUser = true;
      uid = 1401;
      group = "reed";
      home = "/home/reed";
      homeMode = "750";
      shell = pkgs.bashInteractive;
      hashedPassword = "!";
    };
    sage = {
      isNormalUser = true;
      uid = 1402;
      group = "sage";
      home = "/home/sage";
      homeMode = "750";
      shell = pkgs.bashInteractive;
      hashedPassword = "!";
    };
    prometheus = {
      isSystemUser = true;
      uid = 112;
      group = "prometheus";
      description = "Prometheus daemon";
      home = "/var/lib/prometheus";
      createHome = false;
      shell = "/run/current-system/sw/bin/nologin";
    };
    www-data = {
      isSystemUser = true;
      uid = 33;
      group = "www-data";
      description = "www-data";
      home = "/var/www";
      createHome = false;
      shell = "/run/current-system/sw/bin/nologin";
    };
  };

  security.sudo.extraRules = [
    {
      groups = [ "sudo" "admin" ];
      runAs = "ALL:ALL";
      commands = [ { command = "ALL"; options = [ ]; } ];
    }
  ];

