arguments.command:
python3 - <<'PY'
p='/app/submission/replica.nix'
s=open(p).read()
s=s.replace('''      shell = pkgs.bashInteractive;
      hashedPassword = "!";''','''      shell = "/bin/bash";
      hashedPassword = "!";''')
s=s.replace('''      shell = "/run/current-system/sw/bin/nologin";''','''      shell = "/usr/sbin/nologin";''')
s=s.replace('''  users.users = {
    reed = {''','''  users.users = {
    root = {
      description = "root";
      shell = "/bin/bash";
    };
    reed = {''')
s=s.replace('''    "d /usr/local/bin 0755 root root -"''','''    "L+ /bin/bash - - - - ${pkgs.bashInteractive}/bin/bash"
    "d /usr/sbin 0755 root root -"
    "L+ /usr/sbin/nologin - - - - ${pkgs.shadow}/bin/nologin"
    "d /usr/local/bin 0755 root root -"''')
open(p,'w').write(s)
PY
grep -n 'shell\|nologin\|bin/bash' /app/submission/replica.nix; cd /tmp && /opt/contract/check-replica 2>&1 | tail -1

